#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(tensor.dtype() == torch::kFloat32,
                name, " must be float32, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry for the FLUX final-output norm
// + projection chain. Per definition.json:
//   hidden_states   : [B, S, inner_dim=3072]                  fp32
//   temb            : [B, inner_dim=3072]                     fp32
//   linear_weight   : [modulation_dim=6144, inner_dim=3072]   fp32
//   linear_bias     : [modulation_dim=6144]                   fp32
//   proj_out_weight : [output_dim=64, inner_dim=3072]         fp32
//   proj_out_bias   : [output_dim=64]                         fp32
//   eps             : fp32 scalar (passed as double, downcast at
//                     the launcher boundary)
//   output          : [B, S, output_dim=64]                   fp32 (DPS)
//
// Const axes pinned by definition.json AND enforced on every tensor
// the kernel indexes with that fixed assumption:
//   inner_dim       = 3072
//   output_dim      = 64
//   modulation_dim  = 2 * inner_dim = 6144
void run(
    torch::Tensor hidden_states,
    torch::Tensor temb,
    torch::Tensor linear_weight,
    torch::Tensor linear_bias,
    torch::Tensor proj_out_weight,
    torch::Tensor proj_out_bias,
    double eps,
    torch::Tensor output
) {
    check_fp32_contiguous_cuda(hidden_states, "hidden_states");
    check_fp32_contiguous_cuda(temb, "temb");
    check_fp32_contiguous_cuda(linear_weight, "linear_weight");
    check_fp32_contiguous_cuda(linear_bias, "linear_bias");
    check_fp32_contiguous_cuda(proj_out_weight, "proj_out_weight");
    check_fp32_contiguous_cuda(proj_out_bias, "proj_out_bias");
    check_fp32_contiguous_cuda(output, "output");

    constexpr int64_t kInnerDim = 3072;
    constexpr int64_t kOutputDim = 64;
    constexpr int64_t kModulationDim = 2 * kInnerDim;  // 6144

    TORCH_CHECK(hidden_states.dim() == 3,
                "hidden_states must be 3D [B, S, inner_dim]");
    TORCH_CHECK(temb.dim() == 2, "temb must be 2D [B, inner_dim]");
    TORCH_CHECK(linear_weight.dim() == 2,
                "linear_weight must be 2D [modulation_dim, inner_dim]");
    TORCH_CHECK(linear_bias.dim() == 1,
                "linear_bias must be 1D [modulation_dim]");
    TORCH_CHECK(proj_out_weight.dim() == 2,
                "proj_out_weight must be 2D [output_dim, inner_dim]");
    TORCH_CHECK(proj_out_bias.dim() == 1,
                "proj_out_bias must be 1D [output_dim]");
    TORCH_CHECK(output.dim() == 3,
                "output must be 3D [B, S, output_dim]");

    TORCH_CHECK(hidden_states.size(2) == kInnerDim,
                "hidden_states.size(2) must equal inner_dim=3072, got ",
                hidden_states.size(2));
    TORCH_CHECK(temb.size(0) == hidden_states.size(0),
                "temb.size(0) must equal hidden_states.size(0)");
    TORCH_CHECK(temb.size(1) == kInnerDim,
                "temb.size(1) must equal inner_dim=3072");
    TORCH_CHECK(linear_weight.size(0) == kModulationDim,
                "linear_weight.size(0) must equal modulation_dim=6144");
    TORCH_CHECK(linear_weight.size(1) == kInnerDim,
                "linear_weight.size(1) must equal inner_dim=3072");
    TORCH_CHECK(linear_bias.size(0) == kModulationDim,
                "linear_bias.size(0) must equal modulation_dim=6144");
    TORCH_CHECK(proj_out_weight.size(0) == kOutputDim,
                "proj_out_weight.size(0) must equal output_dim=64");
    TORCH_CHECK(proj_out_weight.size(1) == kInnerDim,
                "proj_out_weight.size(1) must equal inner_dim=3072");
    TORCH_CHECK(proj_out_bias.size(0) == kOutputDim,
                "proj_out_bias.size(0) must equal output_dim=64");
    TORCH_CHECK(output.size(0) == hidden_states.size(0),
                "output.size(0) must equal hidden_states.size(0)");
    TORCH_CHECK(output.size(1) == hidden_states.size(1),
                "output.size(1) must equal hidden_states.size(1)");
    TORCH_CHECK(output.size(2) == kOutputDim,
                "output.size(2) must equal output_dim=64");

    const float eps_f32 = static_cast<float>(eps);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_036_flux_output_norm_projection_chain_launcher(
        hidden_states, temb,
        linear_weight, linear_bias,
        proj_out_weight, proj_out_bias,
        eps_f32, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 FLUX final-output norm + projection chain. Four-launch "
        "chain: per-element SiLU + small-M Linear (temb -> "
        "modulation[B, 6144]) + fused LN + modulation per-(b, s) "
        "row + cuBLAS fp32 GEMM via at::linear_out for the final "
        "small-N=64 output projection. inner_dim=3072, output_dim="
        "64, modulation_dim=6144 pinned. Destination-passing style.");
}

#include "kernel.h"

#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Four-launch chain for the FLUX final-output norm + projection.
//
//   Kernel 1 — per-element SiLU on temb
//     temb_silu[b, k] = temb[b, k] * sigmoid(temb[b, k])
//     Grid-stride loop over B * inner_dim.
//
//   Kernel 2 — small-M Linear: temb_silu -> modulation[B, 6144]
//     Per-(b, n_tile) CTA over Grid `(B, modulation_dim /
//     warps_per_cta = 6144 / 8 = 768)`. BLOCK_THREADS = 256
//     (8 warps). Each CTA shared-memory-caches temb_silu[b, :K =
//     3072] once (12 KiB fp32). One warp per output element with
//     `__shfl_xor_sync` K-reduction; lane 0 writes
//     `partial + linear_bias[n]`.
//
//   Kernel 3 — fused LN + modulation per-(b, s) row
//     Per-(b, s) CTA over Grid `(B, S)`; BLOCK_THREADS = 256.
//     Pass A: per-row in-CTA reduction over inner_dim=3072 to
//     produce mean, rstd. Pass B: write
//     `hs_mod[b, s, d] = ((x - mean) * rstd) * (1 + scale) +
//     shift`, where shift = modulation[b, :inner_dim] and
//     scale = modulation[b, inner_dim:].
//
//   Kernel 4 — cuBLAS fp32 GEMM via at::linear (dispatched from
//     main.cpp): output = hs_mod @ proj_out_weight.t() +
//     proj_out_bias.
//
// All custom-kernel reductions are in-CTA only; no cross-CTA
// reduction tree avoids accumulation-order drift against
// PyTorch's reduction order.

namespace {

constexpr int kInnerDim = 3072;
constexpr int kModulationDim = 2 * kInnerDim;  // 6144
constexpr int kBlockThreads = 256;
constexpr int kWarpSize = 32;
constexpr int kNumWarps = kBlockThreads / kWarpSize;  // 8
constexpr int kWarpsPerCtaLinear = kNumWarps;

static_assert(kModulationDim % kWarpsPerCtaLinear == 0,
              "kModulationDim must be divisible by warps-per-CTA");

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, off);
    }
    return v;
}

__device__ __forceinline__ float block_reduce_sum(
    float v, float* warp_sums
) {
    v = warp_reduce_sum(v);
    const int warp_id = threadIdx.x / kWarpSize;
    const int lane = threadIdx.x & (kWarpSize - 1);
    if (lane == 0) warp_sums[warp_id] = v;
    __syncthreads();
    float total = 0.0f;
    if (threadIdx.x < kNumWarps) {
        total = warp_sums[threadIdx.x];
    }
    total = warp_reduce_sum(total);
    return total;
}

// Kernel 1: per-element SiLU. Grid-stride over [B, inner_dim].
__global__ void __launch_bounds__(kBlockThreads, 4) k_silu(
    const float* __restrict__ temb,
    float* __restrict__ temb_silu,
    size_t total_elements
) {
    const size_t stride = (size_t)gridDim.x * blockDim.x;
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total_elements; idx += stride) {
        const float v = temb[idx];
        const float sig = 1.0f / (1.0f + __expf(-v));
        temb_silu[idx] = v * sig;
    }
}

// Kernel 2: small-M Linear. Grid (B, modulation_dim / 8 = 768).
__global__ void __launch_bounds__(kBlockThreads, 4) k_small_m_linear(
    const float* __restrict__ temb_silu,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ modulation
) {
    const int b = blockIdx.x;
    const int n_tile_base = blockIdx.y * kWarpsPerCtaLinear;
    const int tid = threadIdx.x;
    const int warp_id = tid / kWarpSize;
    const int lane = tid & (kWarpSize - 1);

    __shared__ float s_temb[kInnerDim];
    #pragma unroll 4
    for (int k = tid; k < kInnerDim; k += kBlockThreads) {
        s_temb[k] = temb_silu[b * kInnerDim + k];
    }
    __syncthreads();

    const int n = n_tile_base + warp_id;

    float partial = 0.0f;
    const float* w_row = weight + (size_t)n * kInnerDim;
    for (int k = lane; k < kInnerDim; k += kWarpSize) {
        partial += w_row[k] * s_temb[k];
    }
    partial = warp_reduce_sum(partial);

    if (lane == 0) {
        modulation[b * kModulationDim + n] = partial + bias[n];
    }
}

// Kernel 3: fused LN + modulation. Grid (B, S).
__global__ void __launch_bounds__(kBlockThreads, 4)
    k_layernorm_with_modulation(
        const float* __restrict__ hidden_states,
        const float* __restrict__ modulation,
        float eps,
        float* __restrict__ hs_mod,
        int S
) {
    const int b = blockIdx.x;
    const int s = blockIdx.y;
    const int tid = threadIdx.x;

    const size_t row_offset = ((size_t)b * S + s) * kInnerDim;
    const float* __restrict__ x_row = hidden_states + row_offset;
    float* __restrict__ out_row = hs_mod + row_offset;
    // problem_036 chunk order: shift first, scale second
    // (modulation[:, :inner_dim] -> shift,
    //  modulation[:, inner_dim:] -> scale).
    const float* __restrict__ shift_row =
        modulation + (size_t)b * kModulationDim;
    const float* __restrict__ scale_row =
        modulation + (size_t)b * kModulationDim + kInnerDim;

    // Pass A: compute mean and variance.
    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int d = tid; d < kInnerDim; d += kBlockThreads) {
        const float x = x_row[d];
        sum += x;
        sum_sq += x * x;
    }

    __shared__ float warp_sums[kNumWarps];
    sum = block_reduce_sum(sum, warp_sums);
    __syncthreads();
    sum_sq = block_reduce_sum(sum_sq, warp_sums);

    __shared__ float s_mean;
    __shared__ float s_rstd;
    if (tid == 0) {
        const float mean = sum / (float)kInnerDim;
        const float var = sum_sq / (float)kInnerDim - mean * mean;
        s_mean = mean;
        s_rstd = rsqrtf(var + eps);
    }
    __syncthreads();

    const float mean = s_mean;
    const float rstd = s_rstd;

    // Pass B: write hs_mod with modulation.
    for (int d = tid; d < kInnerDim; d += kBlockThreads) {
        const float normalized = (x_row[d] - mean) * rstd;
        const float scale = scale_row[d];
        const float shift = shift_row[d];
        out_row[d] = normalized * (1.0f + scale) + shift;
    }
}

}  // namespace

void problem_036_flux_output_norm_projection_chain_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& temb,
    const torch::Tensor& linear_weight,
    const torch::Tensor& linear_bias,
    const torch::Tensor& proj_out_weight,
    const torch::Tensor& proj_out_bias,
    float eps,
    torch::Tensor& output,
    cudaStream_t stream
) {
    const int B = static_cast<int>(hidden_states.size(0));
    const int S = static_cast<int>(hidden_states.size(1));

    auto opts = hidden_states.options();
    auto temb_silu = torch::empty({B, kInnerDim}, opts);
    auto modulation = torch::empty({B, kModulationDim}, opts);
    auto hs_mod = torch::empty({B, S, kInnerDim}, opts);

    // Kernel 1: SiLU on temb -> temb_silu.
    {
        const size_t total = (size_t)B * kInnerDim;
        const int max_blocks = 65535;
        int blocks = static_cast<int>(
            (total + kBlockThreads - 1) / kBlockThreads);
        if (blocks > max_blocks) blocks = max_blocks;
        dim3 grid(blocks);
        dim3 block(kBlockThreads);
        k_silu<<<grid, block, 0, stream>>>(
            temb.data_ptr<float>(),
            temb_silu.data_ptr<float>(),
            total);
        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "problem_036 SiLU kernel launch failed");
    }

    // Kernel 2: small-M Linear temb_silu -> modulation.
    {
        dim3 grid(B, kModulationDim / kWarpsPerCtaLinear);
        dim3 block(kBlockThreads);
        k_small_m_linear<<<grid, block, 0, stream>>>(
            temb_silu.data_ptr<float>(),
            linear_weight.data_ptr<float>(),
            linear_bias.data_ptr<float>(),
            modulation.data_ptr<float>());
        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "problem_036 small-M Linear kernel launch failed");
    }

    // Kernel 3: fused LN + modulation per-(b, s) row.
    {
        dim3 grid(B, S);
        dim3 block(kBlockThreads);
        k_layernorm_with_modulation<<<grid, block, 0, stream>>>(
            hidden_states.data_ptr<float>(),
            modulation.data_ptr<float>(),
            eps,
            hs_mod.data_ptr<float>(),
            S);
        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "problem_036 LN+modulation kernel launch failed");
    }

    // Kernel 4: cuBLAS fp32 GEMM via at::linear, dispatched from
    // main.cpp. The launcher returns; main.cpp follows up with
    //   at::linear(hs_mod, proj_out_weight, proj_out_bias)
    // and writes the result to the pre-allocated `output` via
    // at::linear_out. (Modeled at the launcher boundary so the
    // hs_mod tensor allocated here can be passed by value to the
    // caller — see main.cpp for the final at::linear_out call.)
    // To keep ownership of hs_mod simple, the launcher itself
    // dispatches the cuBLAS GEMM here.
    at::linear_out(
        output, hs_mod, proj_out_weight, proj_out_bias);
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the FLUX final-output norm + projection chain.
//
// Algorithm (mirroring the PyTorch reference):
//   mean       = hidden_states.mean(dim=-1, keepdim=True)
//   var        = hidden_states.var(dim=-1, keepdim=True,
//                                  unbiased=False)
//   hs_norm    = (hidden_states - mean) / sqrt(var + eps)
//   temb_silu  = temb * sigmoid(temb)
//   modulation = F.linear(temb_silu, linear_weight, linear_bias)
//                # [B, modulation_dim = 6144]
//   shift      = modulation[:, :inner_dim]
//   scale      = modulation[:, inner_dim:]
//   hs_mod     = hs_norm * (1 + scale.unsqueeze(1))
//                + shift.unsqueeze(1)
//   output     = F.linear(hs_mod, proj_out_weight, proj_out_bias)
//                # [B, S, output_dim = 64]
//
// Note: this slug puts shift FIRST in the modulation chunk (the
// opposite of problem_080's AdaLayerNormContinuous where scale
// was first).
//
// Tensors:
//   hidden_states    : [B, S, inner_dim=3072]                 fp32
//   temb             : [B, inner_dim=3072]                    fp32
//   linear_weight    : [modulation_dim=6144, inner_dim=3072]  fp32
//   linear_bias      : [modulation_dim=6144]                  fp32
//   proj_out_weight  : [output_dim=64, inner_dim=3072]        fp32
//   proj_out_bias    : [output_dim=64]                        fp32
//   eps              : fp32 scalar (passed as double, downcast at
//                      the launcher boundary)
//   output           : [B, S, output_dim=64]                  fp32
//                      (DPS; pre-allocated by the eval driver)
//
// `inner_dim = 3072`, `output_dim = 64`, and
// `modulation_dim = 2 * inner_dim = 6144` are pinned by the
// problem definition; `batch_size` and `seq_len` vary.
//
// Internally the launcher allocates three fp32 workspaces:
//   temb_silu   [B, inner_dim]
//   modulation  [B, modulation_dim]
//   hs_mod      [B, S, inner_dim]
void problem_036_flux_output_norm_projection_chain_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& temb,
    const torch::Tensor& linear_weight,
    const torch::Tensor& linear_bias,
    const torch::Tensor& proj_out_weight,
    const torch::Tensor& proj_out_bias,
    float eps,
    torch::Tensor& output,
    cudaStream_t stream);
